# ----------------- BUILDING AD 4: ALL-IN-ONE MASTER GRID AD -----------------
print("--- BUILDING AD 4: ALL-IN-ONE MASTER BRAND SERVICES AD ---")
def build_master_services_ad():
    w, h = 1080, 1920
    canvas = Image.new("RGBA", (w, h), (10, 18, 32))
    draw = ImageDraw.Draw(canvas)
    
    font_title_lg = get_font("bold", 52)
    font_subtitle = get_font("semibold", 28)
    font_badge = get_font("bold", 24)
    font_card_title = get_font("bold", 30)
    font_card_sub = get_font("semibold", 22)
    font_cta_big = get_font("bold", 46)
    font_cta_sub = get_font("bold", 26)
    font_small = get_font("regular", 21)
    font_small_bold = get_font("bold", 22)
    font_pill = get_font("bold", 26)
    
    # 1. Background gradient
    for y in range(h):
        t = y / float(h)
        r = int(10 + t * 8)
        g = int(18 + t * 14)
        b = int(32 + t * 24)
        draw.line([(0, y), (w, y)], fill=(r, g, b))
        
    # Subtle geometric grid pattern or glow
    glow = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    g_draw = ImageDraw.Draw(glow)
    g_draw.ellipse((-200, -200, 600, 600), fill=(14, 165, 233, 40))
    g_draw.ellipse((600, 1000, 1400, 1800), fill=(245, 158, 11, 30))
    canvas = Image.alpha_composite(canvas, glow)
    draw = ImageDraw.Draw(canvas)
    
    # 2. Header Bar (Top Safe Zone: y=130 to 250)
    header_box = (45, 125, 1035, 245)
    header_overlay = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    h_draw = ImageDraw.Draw(header_overlay)
    h_draw.rounded_rectangle(header_box, radius=22, fill=(11, 22, 38, 240), outline=(255, 255, 255, 50), width=2)
    canvas = Image.alpha_composite(canvas, header_overlay)
    draw = ImageDraw.Draw(canvas)
    
    l_h = 95
    l_w = int(logo_img.width * (l_h / logo_img.height))
    logo_scaled = logo_img.resize((l_w, l_h), Image.Resampling.LANCZOS)
    canvas.paste(logo_scaled, (70, 137), mask=logo_scaled)
    
    draw.text((w - 530, 142), "⭐ 4.98 / 5.0  (3,850+ Reviews)", font=font_small_bold, fill=COLOR_AMBER)
    draw.text((w - 530, 172), "🛡️ 5-YEAR STAMPED WARRANTY", font=font_small_bold, fill=(56, 189, 248))
    draw.text((w - 530, 202), "📍 Hyderabad's #1 Safety Net Brand", font=font_small, fill=COLOR_MUTED)
    
    # 3. Hook / Title Zone
    tag_box = (50, 275, 470, 320)
    draw.rounded_rectangle(tag_box, radius=12, fill=COLOR_AMBER)
    draw.text((70, 283), "ALL-IN-ONE SAFETY SOLUTIONS", font=font_badge, fill=COLOR_DARK_TEXT)
    
    draw.text((50, 340), "Complete Safety Netting Services", font=font_title_lg, fill=COLOR_WHITE)
    draw.text((50, 405), "For High-Rise Apartments & Villas", font=font_title_lg, fill=(56, 189, 248))
    draw.text((50, 475), "Certified Fall Protection • Bird Control • Invisible Grills across Hyderabad", font=font_subtitle, fill=COLOR_MUTED)
    
    # 4. 4 Visual Feature Cards (2x2 Grid) (y=535 to 1320)
    card_w = 465
    card_h = 360
    
    cards_data = [
        {
            "img": os.path.join(OUTPUT_DIR, "raw_ad1_child_safety.jpg"),
            "fallback": os.path.join("public", "images", "balcony-safety-net.jpg"),
            "title": "Balcony Safety Nets",
            "desc": "180kg+ Load • 100% Child Proof",
            "tag": "⭐ TOP CHOICE",
            "color": (245, 158, 11)
        },
        {
            "img": os.path.join(OUTPUT_DIR, "raw_ad2_pigeon_net.jpg"),
            "fallback": os.path.join("public", "images", "balcony-pigeon-net.jpg"),
            "title": "Pigeon & Bird Nets",
            "desc": "Zero Mess • Spotless Balconies",
            "tag": "🕊️ 100% PIGEON-FREE",
            "color": (56, 189, 248)
        },
        {
            "img": os.path.join(OUTPUT_DIR, "raw_ad3_invisible_grill.jpg"),
            "fallback": os.path.join("public", "images", "corner-balcony-invisible-grill.jpg"),
            "title": "SS 316 Invisible Grills",
            "desc": "Unblocked View • 400kg Tensile",
            "tag": "💎 MODERN LUXURY",
            "color": (251, 146, 60)
        },
        {
            "img": os.path.join("public", "images", "cricket-practice-net.jpg"),
            "fallback": os.path.join("public", "images", "construction-safety-net.jpg"),
            "title": "Cricket & Turf Nets",
            "desc": "Terrace Practice • High Impact",
            "tag": "🏏 SPORTS & TERRACE",
            "color": (16, 185, 129)
        }
    ]
    
    grid_coords = [
        (50, 535),
        (565, 535),
        (50, 925),
        (565, 925)
    ]
    
    for i, c in enumerate(cards_data):
        gx, gy = grid_coords[i]
        
        # Load and crop image
        src_p = c["img"] if os.path.exists(c["img"]) else c["fallback"]
        if os.path.exists(src_p):
            card_img = Image.open(src_p).convert("RGBA")
            # resize/crop to card_w x card_h
            ci_ratio = card_img.width / card_img.height
            target_ratio = card_w / card_h
            if ci_ratio > target_ratio:
                new_h = card_h
                new_w = int(card_h * ci_ratio)
            else:
                new_w = card_w
                new_h = int(card_w / ci_ratio)
            c_resized = card_img.resize((new_w, new_h), Image.Resampling.LANCZOS)
            cx = (new_w - card_w) // 2
            cy = (new_h - card_h) // 2
            c_cropped = c_resized.crop((cx, cy, cx + card_w, cy + card_h))
            
            # Add rounded corners mask
            mask = Image.new("L", (card_w, card_h), 0)
            m_draw = ImageDraw.Draw(mask)
            m_draw.rounded_rectangle((0, 0, card_w, card_h), radius=18, fill=255)
            
            canvas.paste(c_cropped, (gx, gy), mask=mask)
            
            # Dark gradient at the bottom of the card for text readability
            card_overlay = Image.new("RGBA", (card_w, card_h), (0, 0, 0, 0))
            co_draw = ImageDraw.Draw(card_overlay)
            for y_line in range(160, card_h):
                t_c = (y_line - 160) / float(card_h - 160)
                alpha_c = int(245 * (t_c ** 0.9))
                co_draw.line([(0, y_line), (card_w, y_line)], fill=(11, 20, 36, alpha_c))
            
            # Card border outline
            co_draw.rounded_rectangle((0, 0, card_w, card_h), radius=18, outline=(255, 255, 255, 60), width=2)
            
            # Card tag pill
            tw = co_draw.textlength(c["tag"], font=font_small_bold) + 24
            co_draw.rounded_rectangle((15, 15, 15 + tw, 48), radius=8, fill=(15, 23, 42, 230), outline=c["color"], width=1)
            co_draw.text((27, 21), c["tag"], font=font_small_bold, fill=c["color"])
            
            # Card text
            co_draw.text((20, card_h - 80), c["title"], font=font_card_title, fill=COLOR_WHITE)
            co_draw.text((20, card_h - 44), c["desc"], font=font_card_sub, fill=(203, 213, 225))
            
            canvas.paste(card_overlay, (gx, gy), mask=mask)
            
    # 5. Trust Guarantee Bar (y=1310 to 1420)
    trust_box = (50, 1315, 1030, 1420)
    draw.rounded_rectangle(trust_box, radius=16, fill=(22, 33, 56, 240), outline=COLOR_AMBER, width=2)
    
    t_icon_line = "🛡️ 5-YEAR STAMPED WARRANTY  •  ⚡ 30-MIN SITE ESTIMATE  •  ⭐ 4.98 RATING"
    ti_len = draw.textlength(t_icon_line, font=font_small_bold)
    draw.text((50 + (980 - ti_len) // 2, 1335), t_icon_line, font=font_small_bold, fill=COLOR_AMBER)
    
    t_sub_line = "Over 12,500+ High-Rise Balconies Made Safe Across Hyderabad & Secunderabad"
    ts_len = draw.textlength(t_sub_line, font=font_small)
    draw.text((50 + (980 - ts_len) // 2, 1375), t_sub_line, font=font_small, fill=(241, 245, 249))
    
    # 6. Master CTA Button (Emerald Green WhatsApp) (y=1450 to 1620)
    cta_box = (50, 1450, 1030, 1610)
    cta_overlay = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    c_draw = ImageDraw.Draw(cta_overlay)
    c_draw.rounded_rectangle(cta_box, radius=24, fill=(16, 185, 129, 250), outline=(255, 255, 255, 120), width=3)
    canvas = Image.alpha_composite(canvas, cta_overlay)
    draw = ImageDraw.Draw(canvas)
    
    h_txt = "BOOK FREE DOORSTEP INSPECTION TODAY"
    h_len = draw.textlength(h_txt, font=font_cta_sub)
    draw.text((50 + (980 - h_len) // 2, 1472), h_txt, font=font_cta_sub, fill=(6, 78, 59))
    
    p_txt = "📞 WhatsApp / Call: +91 81069 74046"
    p_len = draw.textlength(p_txt, font=font_cta_big)
    draw.text((50 + (980 - p_len) // 2, 1515), p_txt, font=font_cta_big, fill=COLOR_WHITE)
    
    # 7. Footnotes
    sub_line1 = "Proprietor: Manohar Gosala  |  Starting ₹18 / sq.ft  |  Direct Factory Prices"
    s1_len = draw.textlength(sub_line1, font=font_small_bold)
    draw.text((50 + (980 - s1_len) // 2, 1630), sub_line1, font=font_small_bold, fill=COLOR_AMBER)
    
    sub_line2 = "Kondapur • Gachibowli • Miyapur • Kukatpally • Hitec City • Manikonda • Pragathi Nagar"
    s2_len = draw.textlength(sub_line2, font=font_small)
    draw.text((50 + (980 - s2_len) // 2, 1665), sub_line2, font=font_small, fill=COLOR_MUTED)
    
    # Save
    out_png = os.path.join(OUTPUT_DIR, "ad4_all_in_one_services_status.png")
    out_jpg = os.path.join(OUTPUT_DIR, "ad4_all_in_one_services_status.jpg")
    out_webp = os.path.join(OUTPUT_DIR, "ad4_all_in_one_services_status.webp")
    
    canvas_rgb = canvas.convert("RGB")
    canvas.save(out_png, "PNG")
    canvas_rgb.save(out_jpg, "JPEG", quality=95)
    canvas_rgb.save(out_webp, "WEBP", quality=92)
    print(f"Generated: {out_png}")

build_master_services_ad()
print("--- ALL 4 MOBILE STATUS ADS GENERATED SUCCESSFULLY! ---")
